    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint _value) public payable {
        require(_value > address(c).balance, "need unaffordable value");
        bool reverted; c.sendMoney(address(this), _value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted);
    }
    receive() external payable {}
}

